(* [comment removed for export] *)
Definition pch_hexdone_stmt : Prop :=
  forall rax ra sp gp tp t0x t1x a0 a1 a2 a3 a4 a5 a6 a7
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo shi : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (pe size eol : Z) (g : bool) (j16 junk : list byte),
  pch_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) P IN E lo shi c1 pad7 pad2 p0 bs pe
          [CB 16 j16; C8 (shw (P + 76))] [C8 (wz 0); C8 (wz 0); C8 (wz 0)] g junk ->
  pch_pure sp P IN E lo shi c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  (pc_blim_has c1 = 0 \/ pc_blim_has c1 = 1) ->
  p0 <= pe -> pe + 2 <= eol <= p0 + Z.of_nat (length bs) -> 0 <= size < 2^64 ->
  evt bsegs (pch_postI ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc P IN E lo shi c pad7 pad2 p0 bs m)
    (MS (pch_ms rax sp gp tp t0x t1x (wz eol) a0 a1 a2 a3 a4 a5 a6 a7 (wz (p0 + Z.of_nat (length bs))) (wz (E + 16)) (wz size) (shw (E + 16)) t3 t4 t5 t6 P IN E)
        F (Z_to_bv 64 0xd2d00) fc None m1 (seg_rom bsegs)).

(* [comment removed for export] *)
Local Ltac pch_optget SIDE MU WM FW PAL ST BH BH1 P c1 spv spg :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SDg := fresh "SDg" in let G1 := fresh "G1" in let G2 := fresh "G2" in
    pose proof (pside2_transport _ _ mc _ _ _ _ SIDE MU WM FW) as SDg;
    pose proof (ACONST_shbase _ (pside2_aconst _ _ _ _ _ SDg)) as [G1 G2];
    unfold AGOT_SHBASE, ASHBASE_CELL in G1, G2; unfold wz in G1, G2; rewrite ASHADOW_BASE_val in G2; clear SDg;
    carve_frame 16%nat ST;
    step; st1; step; step; step; clear G1 G2
  end;
  ps_chkin SIDE MU WM FW P 296 (P + 8) PAL ltac:(zstep; zstep; step);
  step; rewrite zxb_b8 by lia; unfold wz;
  step; notrap;
  zstep; replace (Z.land (pc_blim_has c1) 1) with (pc_blim_has c1) by (clear - BH; destruct BH as [Bq|Bq]; rewrite Bq; reflexivity);
  step; (let KA := fresh "KA" in if_cases KA; zify_cond KA; rewrite ?unsigned_lit in KA by lia; [exfalso; clear - KA BH1; lia|]; clear KA);
  step; step; step;
  lazymatch goal with FRg : rw_cells _ _ spg _ |- _ => release_frame FRg ST spv end;
  step.

